// Open opens a connection using either the configured URL or discrete fields.
func Open(cfg config.Config) (*sql.DB, Driver, error) {
	return open(cfg, false)
}

func open(cfg config.Config, migrate bool) (*sql.DB, Driver, error) {
	d, parsedURL, err := parseDatabaseConfig(cfg.Database, migrate)
	if err != nil {
		return nil, 0, err
	}

	driverName := fmt.Sprintf("instrumented-%s", d)

	var dr driver.Driver

	switch d {
	case SQLite:
		dr = &sqlite3.SQLiteDriver{}
	case Postgres:
		dr = &pq.Driver{}
	case MySQL:
		dr = &mysql.MySQLDriver{}
	}

	registered := false

	for _, dd := range sql.Drivers() {
		if dd == driverName {
			registered = true
			break
		}
	}

	if !registered {
		sql.Register(driverName, instrumentedsql.WrapDriver(dr, instrumentedsql.WithTracer(opentracing.NewTracer(false))))
	}

	db, err := sql.Open(driverName, parsedURL.DSN)
	if err != nil {
		return nil, 0, fmt.Errorf("opening db for driver %s: %s", d, redactDatabaseError(err, cfg.Database, parsedURL.DSN))
	}

	db.SetMaxIdleConns(cfg.Database.MaxIdleConn)
	if cfg.Database.MaxOpenConn > 0 {
		db.SetMaxOpenConns(cfg.Database.MaxOpenConn)
	}
	if cfg.Database.ConnMaxLifetime > 0 {
