// Open opens a connection using either the configured URL or discrete fields.
func Open(cfg config.Config) (*sql.DB, Driver, error) {
	db, d, err := open(cfg, false)
	if err != nil {
		return nil, 0, err
	}
	registerMetrics(d, db)
	return db, d, nil
}

func open(cfg config.Config, migrate bool) (*sql.DB, Driver, error) {
	d, parsedURL, err := parseDatabaseConfig(cfg.Database, migrate)
	if err != nil {
		return nil, 0, err
	}

	driverName := fmt.Sprintf("instrumented-%s", d)

	var dr driver.Driver

	switch d {
	case SQLite:
		dr = &sqlite3.SQLiteDriver{}
	case Postgres:
		dr = &pq.Driver{}
	case MySQL:
		dr = &mysql.MySQLDriver{}
	}

	registered := false

	for _, dd := range sql.Drivers() {
		if dd == driverName {
			registered = true
			break
		}
	}

	if !registered {
		sql.Register(driverName, instrumentedsql.WrapDriver(dr, instrumentedsql.WithTracer(opentracing.NewTracer(false))))
	}

	db, err := sql.Open(driverName, parsedURL.DSN)
	if err != nil {
		return nil, 0, fmt.Errorf("opening db for driver %s: %s", d, redactDatabaseError(err, cfg.Database, parsedURL.DSN))
	}

	db.SetMaxIdleConns(cfg.Database.MaxIdleConn)
	if cfg.Database.MaxOpenConn > 0 {
		db.SetMaxOpenConns(cfg.Database.MaxOpenConn)
	}
	if cfg.Database.ConnMaxLifetime > 0 {
		db.SetConnMaxLifetime(cfg.Database.ConnMaxLifetime)
	}
	return db, d, nil
}

func parseDatabaseConfig(cfg config.DatabaseConfig, migrate bool) (Driver, *dburl.URL, error) {
	if strings.TrimSpace(cfg.URL) != "" {
		return parse(cfg.URL, migrate)
	}

	if err := cfg.Validate(); err != nil {
		return 0, nil, err
	}

	var (
		protocol string
		rawURL   string
	)

	switch cfg.Protocol {
	case config.SQLite:
		path := cfg.Path
		if path == "" {
			path = cfg.Name
		}
		rawURL = (&url.URL{Scheme: "file", Path: path}).String()
	case config.Postgres, config.MySQL:
		protocol = cfg.Protocol.String()
		port := cfg.Port
		if port == 0 {
			if cfg.Protocol == config.Postgres {
				port = 5432
			} else {
				port = 3306
			}
		}
		u := &url.URL{
			Scheme: protocol,
			Host:   net.JoinHostPort(cfg.Host, strconv.Itoa(port)),
			Path:   "/" + cfg.Name,
		}
		if cfg.User != "" || cfg.Password != "" {
			u.User = url.UserPassword(cfg.User, cfg.Password)
		}
		rawURL = u.String()
	default:
		return 0, nil, fmt.Errorf("invalid value %d for db.protocol; expected one of: sqlite, postgres, mysql", cfg.Protocol)
	}

	return parse(rawURL, migrate)
}

var (
	driverToString = map[Driver]string{
		SQLite:   "sqlite3",
		Postgres: "postgres",
		MySQL:    "mysql",
	}

	stringToDriver = map[string]Driver{
		"sqlite3":  SQLite,
		"sqlite":   SQLite,
		"postgres": Postgres,
		"mysql":    MySQL,
	}
)

var urlCredentials = regexp.MustCompile(`(?i)(://)[^/@]*@`)

// Driver represents a database driver
type Driver uint8

func (d Driver) String() string {
	return driverToString[d]
}

const (
	_ Driver = iota
	// SQLite ...
	SQLite
	// Postgres ...
	Postgres
	// MySQL ...
	MySQL
)

func parse(rawurl string, migrate bool) (Driver, *dburl.URL, error) {
	url, err := dburl.Parse(rawurl)
	if err != nil {
		return 0, nil, fmt.Errorf("parsing db.url failed: invalid database URL")
	}

	driver := stringToDriver[url.Driver]
	if driver == 0 {
		return 0, nil, fmt.Errorf("unknown database driver %q in db.url; expected sqlite, postgres, or mysql", url.Driver)
	}

	switch driver {
	case MySQL:
		v := url.Query()
		v.Set("multiStatements", "true")
		v.Set("parseTime", "true")
		if !migrate {
			v.Set("sql_mode", "ANSI")
		}
		url.RawQuery = v.Encode()
		// we need to re-parse since we modified the query params
		url, err = dburl.Parse(url.URL.String())

	case SQLite:
		v := url.Query()
		v.Set("cache", "shared")
		v.Set("_fk", "true")
		url.RawQuery = v.Encode()

		// we need to re-parse since we modified the query params
		url, err = dburl.Parse(url.URL.String())
	}

	if err != nil {
		return 0, nil, fmt.Errorf("parsing database connection settings failed")
	}

	return driver, url, err
}

func redactDatabaseError(err error, cfg config.DatabaseConfig, dsn string) string {
	message := err.Error()
	password := cfg.Password
	if password == "" && cfg.URL != "" {
		if parsedURL, err := url.Parse(cfg.URL); err == nil && parsedURL.User != nil {
			password, _ = parsedURL.User.Password()
		}
	}
	if password != "" {
		for _, passwordValue := range []string{password, url.QueryEscape(password), url.PathEscape(password)} {
			message = strings.ReplaceAll(message, passwordValue, "[redacted]")
		}
	}
	if cfg.URL != "" {
		message = strings.ReplaceAll(message, cfg.URL, redactURL(cfg.URL))
	}
	if dsn != "" {
		message = strings.ReplaceAll(message, dsn, "[redacted connection string]")
	}
	message = urlCredentials.ReplaceAllString(message, "$1[redacted]@")
	return message
			Jaeger: JaegerTracingConfig{
				Enabled: false,
				Host:    jaeger.DefaultUDPSpanServerHost,
				Port:    jaeger.DefaultUDPSpanServerPort,
			},
		},

		Database: DatabaseConfig{
			URL:            "file:/var/opt/flipt/flipt.db",
			MigrationsPath: "/etc/flipt/config/migrations",
			MaxIdleConn:    2,
		},

		Meta: MetaConfig{
			CheckForUpdates: true,
		},
	}
}

