151				return errors.New("db.host is required when db.url is not set")
152			}
153			if strings.TrimSpace(c.Name) == "" {
154				return errors.New("db.name is required when db.url is not set")
155			}
370				cfg.Tracing.Jaeger.Host = viper.GetString(tracingJaegerHost)
371			}
372	
373			if viper.IsSet(tracingJaegerPort) {
374				cfg.Tracing.Jaeger.Port = viper.GetInt(tracingJaegerPort)
375			}
376		}
377	
378		// DB. An explicit URL takes precedence. When there is no URL, discrete
379		// database settings replace the default URL rather than being merged into it.
380		protocolSet := viper.IsSet(dbProtocol)
381		var protocol DatabaseProtocol
382		if protocolSet {
383			var err error
384			protocol, err = parseDatabaseProtocol(viper.GetString(dbProtocol))
385			if err != nil {
386				return nil, err
387			}
388		}
389	
390		urlSet := viper.IsSet(dbURL)
391		if urlSet {
392			cfg.Database.URL = viper.GetString(dbURL)
393		} else if databaseFieldsSet() {
394			cfg.Database.URL = ""
395		}
396	
397		// Populate key/value fields only when URL mode is not selected.
398		if strings.TrimSpace(cfg.Database.URL) == "" {
399			if protocolSet {
400				cfg.Database.Protocol = protocol
401			}
402			if viper.IsSet(dbHost) {
403				cfg.Database.Host = viper.GetString(dbHost)
404			}
405			if viper.IsSet(dbPort) {
406				value := viper.GetString(dbPort)
407				port, err := strconv.Atoi(strings.TrimSpace(value))
408				if err != nil || port < 1 || port > 65535 {
409					return nil, fmt.Errorf("invalid value %q for db.port; expected an integer between 1 and 65535", value)
410				}
411				cfg.Database.Port = port
412			}
413			if viper.IsSet(dbUser) {
414				cfg.Database.User = viper.GetString(dbUser)
415			}
416			if viper.IsSet(dbPassword) {
417				cfg.Database.Password = viper.GetString(dbPassword)
418			}
419			if viper.IsSet(dbName) {
420				cfg.Database.Name = viper.GetString(dbName)
421			}
422			if viper.IsSet(dbPath) {
423				cfg.Database.Path = viper.GetString(dbPath)
424			}
425		}
426	
427		if viper.IsSet(dbMigrationsPath) {
428			cfg.Database.MigrationsPath = viper.GetString(dbMigrationsPath)
429		}
430	
431		if viper.IsSet(dbMaxIdleConn) {
432			cfg.Database.MaxIdleConn = viper.GetInt(dbMaxIdleConn)
433		}
434	
435		if viper.IsSet(dbMaxOpenConn) {
436			cfg.Database.MaxOpenConn = viper.GetInt(dbMaxOpenConn)
437		}
438	
439		if viper.IsSet(dbConnMaxLifetime) {
440			cfg.Database.ConnMaxLifetime = viper.GetDuration(dbConnMaxLifetime)
441		}
442	
443		// Meta
444		if viper.IsSet(metaCheckForUpdates) {
445			cfg.Meta.CheckForUpdates = viper.GetBool(metaCheckForUpdates)
446		}
447	
448		if err := cfg.validate(); err != nil {
449			return &Config{}, err
450		}
451		if urlSet || databaseFieldsSet() {
452			if err := cfg.Database.Validate(); err != nil {
453				return &Config{}, err
454			}
455		}
456	
457		return cfg, nil
458	}
