 32	func open(cfg config.Config, migrate bool) (*sql.DB, Driver, error) {
 33		d, parsedURL, err := parseDatabaseConfig(cfg.Database, migrate)
 34		if err != nil {
 35			return nil, 0, err
 36		}
 37	
 38		driverName := fmt.Sprintf("instrumented-%s", d)
 39	
 40		var dr driver.Driver
 41	
 42		switch d {
 43		case SQLite:
 44			dr = &sqlite3.SQLiteDriver{}
 45		case Postgres:
 46			dr = &pq.Driver{}
 47		case MySQL:
 48			dr = &mysql.MySQLDriver{}
 49		}
 50	
 51		registered := false
 52	
 53		for _, dd := range sql.Drivers() {
 54			if dd == driverName {
 55				registered = true
 56				break
 57			}
 58		}
 59	
 60		if !registered {
 61			sql.Register(driverName, instrumentedsql.WrapDriver(dr, instrumentedsql.WithTracer(opentracing.NewTracer(false))))
 62		}
 63	
 64		db, err := sql.Open(driverName, parsedURL.DSN)
 65		if err != nil {
 66			return nil, 0, fmt.Errorf("opening db for driver %s: %s", d, redactDatabaseError(err, cfg.Database, parsedURL.DSN))
 67		}
 68	
 69		db.SetMaxIdleConns(cfg.Database.MaxIdleConn)
 70		if cfg.Database.MaxOpenConn > 0 {
 71			db.SetMaxOpenConns(cfg.Database.MaxOpenConn)
 72		}
 73		if cfg.Database.ConnMaxLifetime > 0 {
 74			db.SetConnMaxLifetime(cfg.Database.ConnMaxLifetime)
 75		}
 76		return db, d, nil
 77	}
