 79	func parseDatabaseConfig(cfg config.DatabaseConfig, migrate bool) (Driver, *dburl.URL, error) {
 80		if strings.TrimSpace(cfg.URL) != "" {
 81			return parse(cfg.URL, migrate)
 82		}
 83	
 84		if err := cfg.Validate(); err != nil {
 85			return 0, nil, err
 86		}
 87	
 88		var (
 89			protocol string
 90			rawURL   string
 91		)
 92	
 93		switch cfg.Protocol {
 94		case config.SQLite:
 95			path := cfg.Path
 96			if path == "" {
 97				path = cfg.Name
 98			}
 99			rawURL = (&url.URL{Scheme: "file", Path: path}).String()
100		case config.Postgres, config.MySQL:
101			protocol = cfg.Protocol.String()
102			port := cfg.Port
103			if port == 0 {
104				if cfg.Protocol == config.Postgres {
105					port = 5432
106				} else {
107					port = 3306
108				}
109			}
110			u := &url.URL{
111				Scheme: protocol,
112				Host:   net.JoinHostPort(cfg.Host, strconv.Itoa(port)),
113				Path:   "/" + cfg.Name,
114			}
115			if cfg.User != "" || cfg.Password != "" {
116				u.User = url.UserPassword(cfg.User, cfg.Password)
117			}
118			rawURL = u.String()
119		default:
120			return 0, nil, fmt.Errorf("invalid value %d for db.protocol; expected one of: sqlite, postgres, mysql", cfg.Protocol)
121		}
122	
123		return parse(rawURL, migrate)
124	}
