160	func parse(rawurl string, migrate bool) (Driver, *dburl.URL, error) {
161		url, err := dburl.Parse(rawurl)
162		if err != nil {
163			return 0, nil, fmt.Errorf("parsing db.url failed: invalid database URL")
164		}
165	
166		driver := stringToDriver[url.Driver]
167		if driver == 0 {
168			return 0, nil, fmt.Errorf("unknown database driver %q in db.url; expected sqlite, postgres, or mysql", url.Driver)
169		}
170	
171		switch driver {
172		case MySQL:
173			v := url.Query()
174			v.Set("multiStatements", "true")
175			v.Set("parseTime", "true")
176			if !migrate {
177				v.Set("sql_mode", "ANSI")
178			}
179			url.RawQuery = v.Encode()
180			// we need to re-parse since we modified the query params
181			url, err = dburl.Parse(url.URL.String())
182	
183		case SQLite:
184			v := url.Query()
185			v.Set("cache", "shared")
186			v.Set("_fk", "true")
187			url.RawQuery = v.Encode()
188	
189			// we need to re-parse since we modified the query params
190			url, err = dburl.Parse(url.URL.String())
191		}
192	
193		if err != nil {
194			return 0, nil, fmt.Errorf("parsing database connection settings failed")
195		}
196	
197		return driver, url, err
198	}
