200	func redactDatabaseError(err error, cfg config.DatabaseConfig, dsn string) string {
201		message := err.Error()
202		password := cfg.Password
203		if password == "" && cfg.URL != "" {
204			if parsedURL, err := url.Parse(cfg.URL); err == nil && parsedURL.User != nil {
205				password, _ = parsedURL.User.Password()
206			}
207		}
208		if password != "" {
209			for _, passwordValue := range []string{password, url.QueryEscape(password), url.PathEscape(password)} {
210				message = strings.ReplaceAll(message, passwordValue, "[redacted]")
211			}
212		}
213		if cfg.URL != "" {
214			message = strings.ReplaceAll(message, cfg.URL, redactURL(cfg.URL))
215		}
 26		logger   *logrus.Entry
 27		migrator *migrate.Migrate
 28	}
