 30	// NewMigrator creates a new Migrator
 31	func NewMigrator(cfg config.Config, logger *logrus.Logger) (*Migrator, error) {
 32		sql, driver, err := open(cfg, true)
 33		if err != nil {
 34			return nil, fmt.Errorf("opening db: %w", err)
 35		}
 36	
 37		var dr database.Driver
 38	
 39		switch driver {
 40		case SQLite:
 41			dr, err = sqlite3.WithInstance(sql, &sqlite3.Config{})
 42		case Postgres:
 43			dr, err = postgres.WithInstance(sql, &postgres.Config{})
 44		case MySQL:
 45			dr, err = mysql.WithInstance(sql, &mysql.Config{})
 46		}
 47	
 48		if err != nil {
 49			return nil, fmt.Errorf("getting db driver for %s: %s", driver, redactDatabaseError(err, cfg.Database, ""))
 50		}
 51	
 52		f := filepath.Clean(fmt.Sprintf("%s/%s", cfg.Database.MigrationsPath, driver))
 53	
 54		mm, err := migrate.NewWithDatabaseInstance(fmt.Sprintf("file://%s", f), driver.String(), dr)
 55		if err != nil {
 56			return nil, fmt.Errorf("opening migrations: %s", redactDatabaseError(err, cfg.Database, ""))
 57		}
 58	
 59		return &Migrator{
 60			migrator: mm,
 61			logger:   logrus.NewEntry(logger),
 62			driver:   driver,
 63		}, nil
 64	}
